#!/usr/bin/python3

# Generate the kernel's table of user programs: kernel/userprogs.h (struct
# proginfo, the count TOTAL_USER_PROGS, and declarations of user_progs and
# find_program()) and kernel/userprogs.c (the table itself, and
# find_program()), from the programs that the build embeds into the kernel
# image.
#
# find_program() lives in the generated file, rather than in a kernel file
# that students edit (such as kernel/utils.c), so that adding it cannot cause
# a merge conflict, and it uses its own string comparison so that it cannot
# collide with a strcmp() of the student's.
#
# Every embedded program is first built (or copied) to user/<name>.elf, and
# `objcopy -I binary` names the start of its image after that path, with each
# character that is not a letter or digit replaced by '_':
#
#   user/<name>.elf  ->  _binary_user_<name>_elf_start
#
# Usage (the Makefile passes the names of the programs it embeds):
#
#   gen_user_prog_info.py --header kernel/userprogs.h \
#       --source kernel/userprogs.c <name> <name> ...
#
# With no names, the script finds the programs itself, using the same rules
# as the Makefile: user/*.c, user/diabolical/*.c and user/prebuilt/*.elf.
# With --list, it just prints the names it would use, one per line.
#
# Each output file is only rewritten if its contents change, so that a build
# that adds or removes no programs recompiles nothing.

import argparse
import os
import re
import sys

PROG_MAXNAME = 16  # bytes in proginfo.name, including the NUL

# Where the Makefile finds programs, relative to the top of the tree
SOURCES = [
    ("user", ".c"),
    ("user/diabolical", ".c"),
    ("user/prebuilt", ".elf"),
]

PROG = "gen_user_prog_info.py"


def error(msg):
    sys.exit(f"{PROG}: error: {msg}")


def warn(msg):
    print(f"{PROG}: warning: {msg}", file=sys.stderr)


def source_files(name):
    """The files that the build could embed as program `name`."""
    paths = [os.path.join(d, name + ext) for d, ext in SOURCES]
    return [p for p in paths if os.path.isfile(p)]


def scan_programs():
    """Find the programs the way the Makefile's wildcards do."""
    names = []
    for d, ext in SOURCES:
        if not os.path.isdir(d):
            continue
        for f in sorted(os.listdir(d)):
            if f.endswith(ext) and os.path.isfile(os.path.join(d, f)):
                names.append(f[: -len(ext)])
    return names


def symbol(name):
    """The linker symbol for the start of program `name`'s ELF image."""
    return "_binary_" + re.sub(r"[^A-Za-z0-9]", "_", f"user/{name}.elf") + "_start"


def check(names):
    """Fail on names that cannot be in the table; warn on odd ones."""
    seen = set()
    for name in names:
        if name in seen:
            files = source_files(name)
            where = " and ".join(files) if files else "the program list"
            error(f"program '{name}' appears twice (from {where}); "
                  "rename one of them")
        seen.add(name)
        if name == "":
            error("empty program name")
        if len(name) > PROG_MAXNAME - 1:
            error(f"program name '{name}' is {len(name)} characters long; "
                  f"names can have at most {PROG_MAXNAME - 1}")
        if not all(c.isprintable() and c not in '"\\' for c in name):
            error(f"program name {name!r} contains characters that cannot "
                  "go in a C string")
        if not re.fullmatch(r"[A-Za-z0-9_]+", name):
            warn(f"program name '{name}' has characters other than letters, "
                 f"digits and '_'; its symbol is {symbol(name)}")


def header_text(names):
    lines = []
    header_start = f"""\
// generated by {PROG} based on the programs in the user/ directory; do not edit
#ifndef _USERPROGS_H
#define _USERPROGS_H

#define PROG_MAXNAME {PROG_MAXNAME}
#define TOTAL_USER_PROGS {len(names)}  // number of entries in user_progs

struct proginfo {{
  char name[PROG_MAXNAME];   // program name (max {PROG_MAXNAME - 1} chars + NUL)
  unsigned char* elf_start;  // start of its ELF image (from the linker)
}};

extern struct proginfo user_progs[TOTAL_USER_PROGS];

// The embedded program called `name`, or nullptr if there is none.
struct proginfo* find_program(const char* name);

// ============================================
// Symbols for all user programs (defined by the linker)
"""

    header_end = """\


#endif
"""

    lines.append(header_start)
    lines += [f"extern unsigned char {symbol(n)}[];" for n in names]
    if names:
        lines.append("")

    lines.append(header_end)

    return "\n".join(lines) + "\n"


def source_text(names):
    lines = [
        f"// generated by {PROG} from the programs the Makefile embeds; do not edit",
        '#include "userprogs.h"',
        "",
    ]
    lines.append("struct proginfo user_progs[TOTAL_USER_PROGS] = {")
    lines += [f'    {{"{n}", {symbol(n)}}},' for n in names]
    lines.append("};")
    lines.append(FIND_PROGRAM)

    return "\n".join(lines) + "\n"


# find_program(), as it appears at the end of userprogs.c. It compares names
# itself rather than calling strcmp(), so that it needs nothing from the rest
# of the kernel.
FIND_PROGRAM = """
// Do two NUL-terminated strings match exactly?
static bool same_name(const char* a, const char* b) {
  while (*a != '\\0' && *a == *b) {
    a++;
    b++;
  }
  return *a == *b;
}

struct proginfo* find_program(const char* name) {
  for (int i = 0; i < TOTAL_USER_PROGS; i++) {
    if (same_name(user_progs[i].name, name)) {
      return &user_progs[i];
    }
  }
  return nullptr;
}"""


def write_if_changed(path, text):
    try:
        with open(path) as f:
            if f.read() == text:
                return
    except FileNotFoundError:
        pass
    with open(path, "w") as f:
        f.write(text)
    print(f"{PROG}: wrote {path}")


def main():
    parser = argparse.ArgumentParser(
        description="Generate the kernel's table of user programs.")
    parser.add_argument("--header", help="where to write userprogs.h")
    parser.add_argument("--source", help="where to write userprogs.c")
    parser.add_argument("--list", action="store_true",
                        help="print the program names and exit")
    parser.add_argument("names", nargs="*",
                        help="the programs to list (default: find automatically)")
    args = parser.parse_args()

    names = args.names if args.names else scan_programs()
    check(names)
    names = sorted(names)

    if args.list:
        print("\n".join(names))
        return
    if not args.header and not args.source:
        parser.error("nothing to do: specify --header and --source (or --list)")
    if args.header:
        write_if_changed(args.header, header_text(names))
    if args.source:
        write_if_changed(args.source, source_text(names))


if __name__ == "__main__":
    main()
